<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue';
import { Edit3, KeyRound, Plus, Save, Trash2, UserPlus, UsersRound, X } from 'lucide-vue-next';
import api, { apiError } from '../services/api';
import { formatDateTime, timezoneFor } from '../utils/datetime';
import { useAuthStore } from '../stores/auth';
const props = defineProps({ householdId: { type: Number, default: null } });
const auth = useAuthStore(); const timezone = timezoneFor(auth.user); const tab = ref('users'); const loading = ref(true); const saving = ref(false); const error = ref(''); const notice = ref(''); const roles = ref([]); const permissions = ref([]); const users = ref([]); const systemRoles = ref([]);
const showRoleForm = ref(false); const editingRole = ref(null); const showUserForm = ref(false); const editingUser = ref(null); const roleForm = reactive({ name: '', permissions: [] }); const userForm = reactive({ name: '', email: '', phone: '', password: '', role: 'family-member', is_active: true });
const permissionGroups = computed(() => Object.entries(permissions.value.reduce((groups, permission) => { (groups[permission.group] ||= []).push(permission); return groups; }, {})));
// Group permissions follow the same <module>.<ability> shape as the API guards.
const abilityLabel = (ability) => ({ view: 'View', create: 'Create', edit: 'Edit', delete: 'Delete', export: 'Export', approve: 'Approve' }[ability] || ability);
const matrixAbilities = computed(() => [...new Set(permissions.value.map((permission) => permission.name.split('.').pop()))]);
const groupAbilities = (group) => [...new Set(group[1].map((permission) => permission.name.split('.').pop()))];
const isGroupGranted = (group) => groupAbilities(group).every((ability) => roleForm.permissions.includes(`${group[0]}.${ability}`));
const toggleGroup = (group) => {
    const names = group[1].map((permission) => permission.name);
    const grant = !isGroupGranted(group);
    names.forEach((name) => {
        const index = roleForm.permissions.indexOf(name);
        if (grant && index < 0) roleForm.permissions.push(name);
        if (!grant && index >= 0) roleForm.permissions.splice(index, 1);
    });
};
const grantAll = () => { roleForm.permissions = [...new Set([...roleForm.permissions, ...permissions.value.map((p) => p.name)])]; };
const clearAll = () => { roleForm.permissions = []; };

// ---- per-user permission setup -------------------------------------------------
const showPermissionForm = ref(false);
const permUser = ref(null);
const permForm = reactive({ permissions: [], loading: false, saving: false, editable: false, role: null });
const permGroups = computed(() => Object.entries(
    permissions.value.reduce((groups, permission) => { (groups[permission.group] ||= []).push(permission); return groups; }, {})
).sort(([a], [b]) => a.localeCompare(b)));
const permCount = computed(() => permForm.permissions.length);
const openPermissions = async (person) => {
    showPermissionForm.value = true; permUser.value = person; permForm.loading = true; permForm.permissions = [];
    try {
        const data = (await api.get(`/settings/users/${person.id}/permissions`)).data;
        permForm.permissions = [...data.assigned]; permForm.editable = data.editable; permForm.role = data.role;
    } catch (e) { error.value = apiError(e); } finally { permForm.loading = false; }
};
const togglePerm = (name) => { const i = permForm.permissions.indexOf(name); i < 0 ? permForm.permissions.push(name) : permForm.permissions.splice(i, 1); };
const togglePermGroup = (group) => {
    const names = group.map((p) => p.name); const grant = !names.every((n) => permForm.permissions.includes(n));
    names.forEach((n) => { const i = permForm.permissions.indexOf(n); if (grant && i < 0) permForm.permissions.push(n); if (!grant && i >= 0) permForm.permissions.splice(i, 1); });
};
const grantAllPerms = () => { permForm.permissions = permissions.value.map((p) => p.name); };
const clearAllPerms = () => { permForm.permissions = []; };
const savePermissions = async () => {
    permForm.saving = true; error.value = '';
    try {
        await api.put(`/settings/users/${permUser.value.id}/permissions`, { permissions: permForm.permissions });
        notice.value = `Permissions updated for ${permUser.value.name}.`; showPermissionForm.value = false; await load();
    } catch (e) { error.value = apiError(e); } finally { permForm.saving = false; }
};
const canManage = computed(() => auth.canArea('users', 'manage'));
const can = (ability) => auth.canArea('users', ability);
const canRole = (ability) => auth.canArea('roles', ability);
const isSuperAdmin = computed(() => auth.isSuperAdmin);
// System roles ship with the app: only a super admin may rewrite them, and none can be deleted.
const lockedRole = (role) => systemRoles.value.includes(role.name);
const canEditRole = (role) => !lockedRole(role) || isSuperAdmin.value;
// Handing out super-admin is a super-admin only action, enforced by the API as well.
const assignableRoles = computed(() => roles.value.filter((role) => isSuperAdmin.value || role.name !== 'super-admin'));
const label = (value) => String(value || '').replaceAll('-', ' ').replace(/\b\w/g, (c) => c.toUpperCase());
const load = async () => { loading.value = true; try { const [access, people] = await Promise.all([api.get('/settings/access'), props.householdId ? api.get(`/households/${props.householdId}/users`) : api.get('/settings/users')]); roles.value = access.data.roles; permissions.value = access.data.permissions; systemRoles.value = access.data.system_roles; users.value = people.data.data; } catch (e) { error.value = apiError(e); } finally { loading.value = false; } };
const resetRole = () => { editingRole.value = null; roleForm.name = ''; roleForm.permissions = []; showRoleForm.value = true; };
const editRole = (role) => { editingRole.value = role; roleForm.name = role.name; roleForm.permissions = [...role.permissions]; showRoleForm.value = true; };
const togglePermission = (name) => { const index = roleForm.permissions.indexOf(name); index < 0 ? roleForm.permissions.push(name) : roleForm.permissions.splice(index, 1); };
const saveRole = async () => { saving.value = true; error.value = ''; try { const body = { name: roleForm.name, permissions: roleForm.permissions }; editingRole.value ? await api.put(`/settings/roles/${editingRole.value.id}`, body) : await api.post('/settings/roles', body); showRoleForm.value = false; notice.value = 'Role saved.'; await load(); } catch (e) { error.value = apiError(e); } finally { saving.value = false; } };
const deleteRole = async (role) => { if (!window.confirm(`Delete role ${role.name}?`)) return; try { await api.delete(`/settings/roles/${role.id}`); await load(); } catch (e) { error.value = apiError(e); } };
const resetUser = () => { editingUser.value = null; Object.assign(userForm, { name: '', email: '', phone: '', password: '', role: 'family-member', is_active: true }); showUserForm.value = true; };
const editUser = (person) => { editingUser.value = person; Object.assign(userForm, { name: person.name, email: person.email, phone: person.phone || '', password: '', role: person.roles?.[0]?.name || 'family-member', is_active: person.is_active }); showUserForm.value = true; };
const saveUser = async () => { saving.value = true; error.value = ''; try { const body = { ...userForm }; if (editingUser.value) { delete body.is_active; await api.put(`/settings/users/${editingUser.value.id}`, body); } else await api.post('/settings/users', body); showUserForm.value = false; notice.value = 'User saved.'; await load(); } catch (e) { error.value = apiError(e); } finally { saving.value = false; } };
const deleteUser = async (person) => { if (!window.confirm(`Delete ${person.name}?`)) return; try { await api.delete(`/settings/users/${person.id}`); await load(); } catch (e) { error.value = apiError(e); } };
const toggleActive = async (person) => { try { await api.put(`/settings/users/${person.id}`, { is_active: !person.is_active, role: person.roles?.[0]?.name }); person.is_active = !person.is_active; } catch (e) { error.value = apiError(e); } };
watch(() => props.householdId, () => load());
onMounted(load);
</script>
<template>
    <div class="space-y-4"><div class="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><p class="eyebrow flex items-center gap-2"><KeyRound :size="13" /> Access control</p><h2 class="mt-1 text-xl font-semibold">Users, roles & permissions</h2><p class="mt-1 text-xs text-[#719b8e]">Every user receives only the actions granted by their role.</p></div><div class="flex gap-2"><button v-if="canRole('view')" class="btn-secondary" @click="tab = tab === 'users' ? 'roles' : 'users'"><UsersRound :size="15" /> {{ tab === 'users' ? 'Manage roles' : 'Manage users' }}</button><button v-if="tab === 'users' && can('create')" class="btn-primary" @click="resetUser"><UserPlus :size="15" /> Add user</button><button v-else-if="canRole('create')" class="btn-primary" @click="resetRole"><Plus :size="15" /> Create role</button><span v-else class="badge">Read-only</span></div></div><p v-if="error" class="rounded-xl border border-rose-300/20 bg-rose-400/10 px-3 py-2 text-xs text-rose-200">{{ error }}</p><p v-if="notice" class="rounded-xl border border-emerald-300/20 bg-emerald-300/10 px-3 py-2 text-xs text-emerald-100">{{ notice }}</p><div v-if="loading" class="h-40 rounded-2xl skeleton"></div><template v-else-if="tab === 'users'"><div class="overflow-x-auto rounded-2xl border border-emerald-100/10"><table class="w-full min-w-[650px] text-left text-sm"><thead class="text-[10px] uppercase tracking-[.14em] text-[#679689]"><tr><th class="px-4 py-3">User</th><th class="px-4 py-3">Role</th><th class="px-4 py-3">Status</th><th class="px-4 py-3">Last login</th><th></th></tr></thead><tbody><tr v-for="person in users" :key="person.id" class="table-row"><td class="px-4 py-3"><p class="font-medium text-white">{{ person.name }}</p><p class="text-[10px] text-[#6e9b8e]">{{ person.email }}<span v-if="person.phone"> · {{ person.phone }}</span></p></td><td class="px-4 py-3"><span class="badge badge-blue">{{ label(person.roles?.[0]?.name) }}</span></td><td class="px-4 py-3"><button class="badge disabled:cursor-not-allowed disabled:opacity-50" :class="person.is_active ? 'badge-green' : 'badge-red'" :disabled="!can('edit')" :title="can('edit') ? 'Toggle account' : 'users.edit is required'" @click="toggleActive(person)">{{ person.is_active ? 'Active' : 'Disabled' }}</button></td><td class="px-4 py-3 text-xs text-[#8eb8aa]">{{ person.last_login_at ? formatDateTime(person.last_login_at, timezone) : 'Never' }}</td><td class="px-4 py-3 text-right"><button v-if="canRole('edit')" class="btn-secondary mr-1 px-2.5 py-1 text-[10px]" title="Set permissions" @click="openPermissions(person)"><KeyRound :size="12" /> Permissions</button><button v-if="can('edit')" class="icon-btn h-8 w-8" title="Edit user" @click="editUser(person)"><Edit3 :size="14" /></button><button v-if="can('delete')" class="icon-btn ml-1 h-8 w-8 text-rose-200/70" title="Delete user" @click="deleteUser(person)"><Trash2 :size="14" /></button></td></tr></tbody></table></div></template><template v-else><div class="grid gap-3 md:grid-cols-2"><div v-for="role in roles" :key="role.id" class="rounded-2xl border border-emerald-100/10 bg-[#082b27] p-4"><div class="flex items-start justify-between gap-2"><div><p class="text-sm font-semibold text-white">{{ label(role.name) }}</p><p class="mt-1 text-[10px] text-[#6e9b8e]">{{ role.permissions.length }} permissions · {{ users.filter((person) => person.roles?.[0]?.name === role.name).length }} users</p></div><span v-if="systemRoles.includes(role.name)" class="badge badge-amber">System</span></div><div class="mt-3 flex flex-wrap gap-1"><span v-for="permission in role.permissions.slice(0, 4)" :key="permission" class="badge badge-blue">{{ permission }}</span><span v-if="role.permissions.length > 4" class="badge">+{{ role.permissions.length - 4 }}</span></div><div class="mt-4 flex flex-wrap items-center gap-2"><button v-if="canEditRole(role)" class="btn-secondary px-3 py-1.5 text-xs" @click="editRole(role)"><Edit3 :size="13" /> Edit</button><button v-if="!lockedRole(role) && canRole('delete')" class="icon-btn h-8 w-8 text-rose-200/70" title="Delete role" @click="deleteRole(role)"><Trash2 :size="13" /></button><p v-if="!canEditRole(role)" class="self-center text-[10px] text-[#5f8b80]">Only a super admin can change this role.</p></div></div></div></template></div>
    <Teleport to="body"><div v-if="showPermissionForm" class="fixed inset-0 z-[80] flex items-center justify-center p-4"><div class="absolute inset-0 bg-black/70 backdrop-blur-sm" @click="showPermissionForm = false"></div><div class="glass max-h-[90vh] w-full max-w-4xl overflow-y-auto rounded-2xl p-5"><div class="flex items-start justify-between gap-3"><div><p class="eyebrow">User permissions</p><h2 class="mt-1 text-xl font-semibold">{{ permUser?.name }}</h2><p class="mt-1 text-xs text-[#719b8e]">{{ permUser?.email }}<span v-if="permForm.role"> · currently {{ label(permForm.role.name) }}</span></p></div><button class="icon-btn" @click="showPermissionForm = false"><X :size="16" /></button></div><p v-if="!permForm.editable" class="mt-4 rounded-xl bg-amber-300/10 px-3 py-2 text-xs text-amber-100">The super admin account always has full access, so its permissions cannot be changed.</p><div v-else class="mt-4 flex flex-wrap items-center justify-between gap-2"><p class="text-xs text-[#8eb8aa]">Tick every action this person may perform. Saving gives them a personal role, so nobody else is affected.</p><div class="flex gap-2"><button class="btn-secondary px-3 py-1 text-[11px]" @click="grantAllPerms">Select all</button><button class="btn-secondary px-3 py-1 text-[11px]" @click="clearAllPerms">Clear all</button></div></div><div v-if="permForm.loading" class="mt-4 h-40 rounded-2xl skeleton"></div><div v-else class="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-3"><div v-for="group in permGroups" :key="group[0]" class="rounded-xl border border-emerald-100/10 bg-[#082b27] p-3"><div class="mb-2 flex items-center justify-between gap-2"><p class="text-xs font-semibold text-white">{{ label(group[0]) }}</p><button class="text-[10px] text-emerald-200/70 hover:text-emerald-100" :disabled="!permForm.editable" @click="togglePermGroup(group[1])">{{ group[1].every((permission) => permForm.permissions.includes(permission.name)) ? 'None' : 'All' }}</button></div><label v-for="permission in group[1]" :key="permission.name" class="flex cursor-pointer items-center gap-2 py-1 text-[11px] text-[#a7cbbf]"><input type="checkbox" class="h-3.5 w-3.5 accent-emerald-300 disabled:cursor-not-allowed disabled:opacity-40" :disabled="!permForm.editable" :checked="permForm.permissions.includes(permission.name)" @change="togglePerm(permission.name)"/>{{ permission.name }}</label></div></div><p v-if="!permForm.loading" class="mt-4 text-[10px] text-[#5f8b80]">{{ permCount }} of {{ permissions.length }} permissions selected.</p><p v-if="error" class="mt-3 text-xs text-rose-200">{{ error }}</p><div class="mt-5 flex justify-end gap-2"><button class="btn-secondary" @click="showPermissionForm = false">Cancel</button><button v-if="permForm.editable" class="btn-primary" :disabled="permForm.saving" @click="savePermissions"><Save :size="15" />{{ permForm.saving ? 'Saving…' : 'Save permissions' }}</button></div></div></div></Teleport>
    <Teleport to="body"><div v-if="showRoleForm" class="fixed inset-0 z-[80] flex items-center justify-center p-4"><div class="absolute inset-0 bg-black/70 backdrop-blur-sm" @click="showRoleForm = false"></div><form class="glass max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-2xl p-5" @submit.prevent="saveRole"><div class="flex items-center justify-between"><div><p class="eyebrow">Role builder</p><h2 class="mt-1 text-xl font-semibold">{{ editingRole ? 'Edit role' : 'Create role' }}</h2></div><button type="button" class="icon-btn" @click="showRoleForm = false"><X :size="16" /></button></div><div class="mt-4"><label class="label">Role name</label><input v-model="roleForm.name" class="field" placeholder="e.g. accountant" required/></div><div class="mt-4 flex flex-wrap items-center justify-between gap-2"><p class="text-xs text-[#8eb8aa]">Tick the actions this role may perform in each area.</p><div class="flex gap-2"><button type="button" class="btn-secondary px-3 py-1 text-[11px]" @click="grantAll">Select all</button><button type="button" class="btn-secondary px-3 py-1 text-[11px]" @click="clearAll">Clear all</button></div></div><div class="mt-3 overflow-x-auto rounded-xl border border-emerald-100/10"><table class="w-full min-w-[520px] text-left text-xs"><thead class="bg-[#062220] text-[10px] uppercase tracking-[.12em] text-[#679689]"><tr><th class="px-3 py-2">Area</th><th v-for="ability in matrixAbilities" :key="ability" class="px-2 py-2 text-center">{{ abilityLabel(ability) }}</th><th class="px-2 py-2 text-center">All</th></tr></thead><tbody><tr v-for="group in permissionGroups" :key="group[0]" class="border-t border-emerald-100/5"><td class="px-3 py-1.5 font-medium text-white">{{ label(group[0]) }}</td><td v-for="ability in matrixAbilities" :key="ability" class="px-2 py-1.5 text-center"><input type="checkbox" class="h-3.5 w-3.5 accent-emerald-300 disabled:opacity-20" :disabled="!groupAbilities(group).includes(ability)" :checked="roleForm.permissions.includes(`${group[0]}.${ability}`)" @change="togglePermission(`${group[0]}.${ability}`)"/></td><td class="px-2 py-1.5 text-center"><input type="checkbox" class="h-3.5 w-3.5 accent-emerald-300" :checked="isGroupGranted(group)" @change="toggleGroup(group)"/></td></tr></tbody></table></div><p class="mt-2 text-[10px] text-[#5f8b80]">{{ roleForm.permissions.length }} of {{ permissions.length }} permissions selected.</p><div class="mt-5 flex justify-end gap-2"><button type="button" class="btn-secondary" @click="showRoleForm = false">Cancel</button><button class="btn-primary" :disabled="saving"><Save :size="15" />{{ saving ? 'Saving…' : 'Save role' }}</button></div></form></div></Teleport>
    <Teleport to="body"><div v-if="showUserForm" class="fixed inset-0 z-[80] flex items-center justify-center p-4"><div class="absolute inset-0 bg-black/70 backdrop-blur-sm" @click="showUserForm = false"></div><form class="glass w-full max-w-md rounded-2xl p-5" @submit.prevent="saveUser"><div class="flex items-center justify-between"><div><p class="eyebrow">User account</p><h2 class="mt-1 text-xl font-semibold">{{ editingUser ? 'Edit user' : 'Create user' }}</h2></div><button type="button" class="icon-btn" @click="showUserForm = false"><X :size="16" /></button></div><div class="mt-4 space-y-3"><div><label class="label">Full name</label><input v-model="userForm.name" class="field" required/></div><div><label class="label">Email</label><input v-model="userForm.email" type="email" class="field" required/></div><div><label class="label">Mobile</label><input v-model="userForm.phone" class="field"/></div><div v-if="!editingUser"><label class="label">Temporary password</label><input v-model="userForm.password" type="password" minlength="8" class="field" required/></div><div><label class="label">Role</label><select v-model="userForm.role" class="field" required><option v-for="role in assignableRoles" :key="role.id" :value="role.name">{{ label(role.name) }}</option></select></div><label class="flex items-center gap-2 text-xs text-[#a7cbbf]"><input v-model="userForm.is_active" type="checkbox" class="accent-emerald-300"/> Account active</label></div><p v-if="error" class="mt-3 text-xs text-rose-200">{{ error }}</p><div class="mt-5 flex justify-end gap-2"><button type="button" class="btn-secondary" @click="showUserForm = false">Cancel</button><button class="btn-primary" :disabled="saving"><UserPlus :size="15" />{{ saving ? 'Saving…' : 'Save user' }}</button></div></form></div></Teleport>
</template>
